    ["green Seed Afterglow."] = "Seed Afterglow verde.",
    ["near Cloister of Tides entrance"] = "cerca de la entrada de la Cloister of Tides",
    ["orange Seed Afterglow."] = "Seed Afterglow naranja.",
    ["red Seed Afterglow."] = "Seed Afterglow rojo.",
    ["silver Seed Afterglow."] = "Seed Afterglow plateado.",
